@startuml

class GasStation {
  +id : string
  +address : string
}

class FuelPump {
  +number : int
  +isSelfService : boolean
}

class Fuel {
  +name : string
  +octaneRating : int
}

class DailyPrice {
  +date : date
  +pricePerLiter : float
}

class FuelPurchase {
  +id : string
  +litersDispensed : float
}

GasStation "1" *-- "0..12" FuelPump
FuelPump "*" -- "*" Fuel
GasStation "1" -- "*" DailyPrice
DailyPrice "*" -- "1" Fuel
FuelPump "1" -- "*" FuelPurchase
FuelPurchase "*" -- "1" FuelPump
FuelPurchase "*" -- "1" DailyPrice
FuelPurchase "*" -- "1" Fuel

@enduml

